getIronSettings();
function getIronSettings(){
	if(STS.ironSettings){
		let irons = Object.entries(STS.ironSettings);
		irons.forEach(i => {
			let name = i[0];
			let value = i[1];
			STS[name] = value;
		});
	}else{
		STS.ironSettings = {};
		let irons = Object.entries(STS.ironSettings);
		irons.forEach(i => {
			let name = i[0];
			let value = i[1];
			STS[name] = value;
		});
	}
}
