function dupeDetect(){
    if($("#StarTubeDuplicateDetector")==null){
        // This is used for detecting whether or not the user has multiple versions of Gplex Extended for YouTube enabled, as that almost never goes well
        // Each Gplex Extended for YouTube version has its own unique ID so Gplex Extended for YouTube versions can determine what other version of Gplex Extended for YouTube is running alongside them.
        // Only supports Gplex Extended for YouTube stable and beta 2.3.1 and later.
        let cont=$("body");
        let nE=document.createElement("div");
        nE.id="StarTubeDuplicateDetector";
        nE.setAttribute("st-id",STUID);
        nE.setAttribute("st-ver",currStarVer);
        cont.insertBefore(nE,cont.children[0]);
    }else{
        let st_id=$("#StarTubeDuplicateDetector").getAttribute("st-id");
        let ver=$("#StarTubeDuplicateDetector").getAttribute("st-ver");
        if(ver==null){
            ver="2.3.1 or earlier";
        }
        if(st_id==STUID){
        }else{
            alert("You have another version of Gplex Extended for YouTube installed: "+ver+" (the version of Gplex Extended for YouTube giving you this message is: "+currStarVer+"). Having multiple versions of Gplex Extended for YouTube installed is almost never a good idea. Please disable one of them.");
        }
    }
}
