    function movePlayerMenuItems(){
        let tM;
        let nH;
        var V3_SET=localStorage.getItem("v3_local_db");
        if($(".ytp-menu .ytp-menu-row:nth-child(4)")){
            let hasSubtitles=false;
            let hasAT=false;
            let hasAP=true;
            if(window.location.href.includes("list")){
                hasAP=false;
            }
            $("body .v3").removeAttribute("has-at");
            if($(".ytp-menu .ytp-menu-row:nth-child(6)")){
                hasSubtitles=true;
            }
            if($(".ytp-menu .ytp-menu-row:nth-child(7)")){
                hasAT=true;
                $("body .v3").setAttribute("has-at","");
            }
            if($("#st-pl-settings .ytp-menu-row")){
                document.querySelectorAll("#st-pl-settings .ytp-menu-row").forEach(i=>{
                    i.remove();
                });
            }else{
                if(hasAT==true){
                    // subtitles
                    tM=$(".ytp-menu .ytp-menu-row:nth-child(5) .ytp-drop-down-menu");
                    nH=$("#st-subtitles-page .st-plm-content");
                    nH.append(tM);
                    // audio track
                    tM=$(".ytp-menu .ytp-menu-row:nth-child(6) .ytp-drop-down-menu");
                    nH=$("#st-audio-track-page .st-plm-content");
                    nH.append(tM);
                    // quality
                    tM=$(".ytp-menu .ytp-menu-row:nth-child(7) .ytp-drop-down-menu");
                    nH=$("#st-quality-page .st-plm-content");
                    nH.append(tM);
                }else if(hasSubtitles==true){
                    // subtitles
                    tM=$(".ytp-menu .ytp-menu-row:nth-child(5) .ytp-drop-down-menu");
                    nH=$("#st-subtitles-page .st-plm-content");
                    nH.append(tM);
                    // quality
                    tM=$(".ytp-menu .ytp-menu-row:nth-child(6) .ytp-drop-down-menu");
                    nH=$("#st-quality-page .st-plm-content");
                    nH.append(tM);
                }else{
                    // quality
                    tM=$(".ytp-menu .ytp-menu-row:nth-child(5) .ytp-drop-down-menu");
                    nH=$("#st-quality-page .st-plm-content");
                    nH.append(tM);
                }
                tM=$(".ytp-menu .ytp-menu-row:nth-child(4) .ytp-drop-down-menu");
                nH=$("#st-speed-page .st-plm-content");
                nH.append(tM);
            }
            // autoplay
            // annot
            // speed
            tM=$(".ytp-menu .ytp-menu-row:nth-child(4)");
            nH=$("#st-main-page .st-pl-menuitem:nth-child(4)");
            nH.append(tM);
            if(hasAT==true){
                // subtitles
                tM=$(".ytp-menu .ytp-menu-row:nth-child(4)");
                nH=$("#st-main-page .st-pl-menuitem:nth-child(5)");
                nH.append(tM);
                // audio track
                tM=$(".ytp-menu .ytp-menu-row:nth-child(4)");
                nH=$("#st-main-page .st-pl-menuitem:nth-child(6)");
                nH.append(tM);
                // quality
                tM=$(".ytp-menu .ytp-menu-row:nth-child(4)");
                nH=$("#st-main-page .st-pl-menuitem:nth-child(7)");
                nH.append(tM);
                tM=$(".st-pl-subtitles .ytp-menu-cell:last-child");
                nH=$("#st-subtitles-page .st-plm-header");
                nH.append(tM);
            }else if(hasSubtitles==true){
                // subtitles
                tM=$(".ytp-menu .ytp-menu-row:nth-child(4)");
                nH=$("#st-main-page .st-pl-menuitem:nth-child(5)");
                nH.append(tM);
                // quality
                tM=$(".ytp-menu .ytp-menu-row:nth-child(4)");
                nH=$("#st-main-page .st-pl-menuitem:nth-child(7)");
                nH.append(tM);
                tM=$(".st-pl-subtitles .ytp-menu-cell:last-child");
                nH=$("#st-subtitles-page .st-plm-header");
                nH.append(tM);
                $("#st-main-page .st-pl-menuitem:nth-child(6)").classList.add("none");
            }else{
                // quality
                tM=$(".ytp-menu .ytp-menu-row:nth-child(4)");
                nH=$("#st-main-page .st-pl-menuitem:nth-child(7)");
                nH.append(tM);
                $("#st-main-page .st-pl-menuitem:nth-child(5)").classList.add("none");
                $("#st-main-page .st-pl-menuitem:nth-child(6)").classList.add("none");
            }
            if(hasAP==false){
                $("#st-main-page .st-pl-menuitem:nth-child(1)").classList.add("none");
            }
        }
    }
