    function createSetting(i,container,n,theSet){
        let newE=document.createElement("div");
        newE.classList="astro-setting astro-radio-setting";
        newE.setAttribute("c",theSet);
        newE.setAttribute("value",i.value);
        newE.innerHTML=ugfTT(STH.astroSetting);
        container.insertBefore(newE,container.children[n]);
        newE.querySelector(".astro-setting-title span").textContent=i.name;
        if(i.mText){
            let mT=i.mText;
            let aM=newE.querySelector(".astro-minitext");
            aM.innerHTML=ugfTT(mT.text);
            if(mT.color){
                aM.classList.add("astro-"+mT.color);
            }
        }
        if(i.new){
            let conta=newE.querySelector(".astro-setting-title");
            let newerE=document.createElement("div");
            newerE.classList.add("st-new");
            newerE.innerHTML=ugfTT(`
            <span>New in ${updateStarVer}</span>
            `);
            conta.append(newerE);
        }
    }
    function createSector(i,container,n,theSet,ix){
        let newE=document.createElement("div");
        newE.classList="astro-sector";
        newE.innerHTML=ugfTT(STH.astroSector);
        container.insertBefore(newE,container.children[n]);
        newE.querySelector("h5").textContent=i.sectorTitle.text;
        let sectorSets=newE.querySelector(".astro-sector-settings");
        let settNumb=1;
        i.opts.forEach(i=>{
            if(i.opt){
                createSetting(i.opt,sectorSets,settNumb,theSet);
            }else{
                createSector(i.sector,newE,settNumb,theSet);
            }
            settNumb++;
        });
    }
    function createCLItem(i,container,n){
        let newE=document.createElement("div");
        newE.classList="st-cl";
        newE.innerHTML=ugfTT(STH.astroChangelogItem);
        container.insertBefore(newE,container.children[n]);
        newE.querySelector("span").innerHTML=ugfTT(i.text);
    }
    function createCLSector(i,container,n){
        let newE=document.createElement("div");
        newE.classList="st-cl-sect";
        newE.innerHTML=ugfTT(STH.astroChangelogSection);
        container.insertBefore(newE,container.children[n]);
        newE.querySelector("b").textContent="Gplex Extended for YouTube "+i.version+" Changelog";
        let sectorSets=newE.querySelector(".st-cl-items");
        let settNumb=1;
        i.items.forEach(i=>{
            if(i.item){
                createCLItem(i.item,sectorSets,settNumb);
            }
            settNumb++;
        });
    }
    function createSpecialSection(tab,ix,n){
        let conta=$("[state-id='"+tab+"'] .astro-scroller-inner");
        nE=document.createElement("div");
        nE.id="st-changelog";
        nE.classList="astro-section";
        nE.innerHTML=ugfTT(`
        <button id="st-cl-expander" class="stx-trigger" stx-target="#st-changelog" stx-trigger-type="attrib-tog" stx-attrib="expanded">
                                                    <div id="st-cl-expand" style="TEXT"><span class="yt-uix-button-content"><span class="run">Show more</span></span></div>
                                                    <div id="st-cl-collapse" style="TEXT"><span class="yt-uix-button-content"><span class="run">Show less</span></span></div>
                                                </button>
        `);
        conta.insertBefore(nE,conta.children[n]);
        let setNumb=1;
        ix.section.changelog.forEach(i=>{
            if(i.sector){
                if(currStarChan=="Beta"&&i.sector.beta!==null){
                    createCLSector(i.sector,nE,setNumb);
                }else if(i.sector.beta==null){
                    createCLSector(i.sector,nE,setNumb);
                }
            }
            setNumb++;
        });
    }
    function createSection(tab,ix,n){
        let conta=$("[state-id='"+tab+"'] .astro-scroller-inner");
        nE=document.createElement("div");
        nE.id=ix.section.id;
        nE.classList="astro-section";
        nE.innerHTML=ugfTT(STH.astroSection);
        conta.insertBefore(nE,conta.children[n]);
        nE.querySelector("h4").textContent=ix.section.title.text;
        if(ix.section.desc){
            nE.querySelector(".astro-description span").innerHTML=ugfTT(ix.section.desc.text);
        }
        if(ix.section.cW){
            nE.querySelector(".astro-cw-cont").innerHTML=ugfTT(ix.section.cW.text);
        }
        if(ix.section.new){
          //  nE.querySelector(".astro-title");
        }
        let setNumb=2;
        let theSet=ix.section.id;
        ix.section.opts.forEach(i=>{
            if(i.opt){
                createSetting(i.opt,nE,setNumb,theSet);
            }else{
                createSector(i.sector,nE,setNumb,theSet);
            }
            setNumb++;
        });
        if(ix.section.new){
            let conta=nE.querySelector(".astro-title");
            let newerE=document.createElement("div");
            newerE.classList.add("st-new");
            newerE.innerHTML=ugfTT(`
            <span>New in ${updateStarVer}</span>
            `);
            conta.append(newerE);
        }
    }
    radioSets.pages.forEach(i=>{
        let obj=i.page;
        let tab=obj.tab;
        let sectNumb=0;
        obj.sections.forEach(ix=>{
            if(ix.section.specialTypeId && ix.section.specialTypeId=="changelog"){
                createSpecialSection(tab,ix,sectNumb);
            }else{
                createSection(tab,ix,sectNumb);
            }
            sectNumb++;
        });
    });
