        add("lr", get("UGF_PREF_LR"));
        add("hl", get("UGF_PREF_HL"));
        add("gl", get("UGF_PREF_GL"));
        const num = get("UGF_PREF_NUM");
        add("num", num && num !== "10" ? num : "");
