function ugfMobileWanted() {
    const m = ugfMobileMode();
    if (m === "off") {
        return false;
    }
    try {
        if (sessionStorage.getItem("ugf_m_classic") === "1") {
            return false;
        }
    } catch (e) {}
    return ugfPhoneLayout();
}
function ugfMobileLayout() {
    let L = null;
    try {
        L = window.localStorage.getItem("UGF_LAYOUT");
    } catch (e) {}
    if (!L) {
        try {
            L = ugfSharedLayout(GM_getValue, null);
        } catch (e) {}
    }
    return String(L || "2015");
}
// the Gplex layout -> the mobile site of that time
function ugfMobileEra(L) {
    const y = parseInt(L, 10);
    if (!y) {
        return L === "retro" ? "a" : "d";
    }
    if (y <= 2010) {
        return "a";
    }
    if (y <= 2012) {
        return "b1";
    }
    if (L === "2013" || L === "2013L") {
        return "b2";
    }
    if (y === 2014 || L === "2015" || L === "2015L") {
        return "c";
    }
    return "d";
}
function ugfMobileYear(L, era) {
    const y = parseInt(L, 10) || 2015;
    if (era === "a") {
        return Math.min(2010, Math.max(2008, y));
    }
    if (era === "b2") {
        return 2013;
    }
    return y;
}
// the Images and Videos home pages: /imghp and /videohp, or the /search?udm=2 (no search yet)
// Google now sends them on to
function ugfMobileVertical() {
    const p = window.location.pathname;
    let q;
    try {
        q = new URLSearchParams(window.location.search);
    } catch (e) {
        return "";
    }
    if (q.get("q")) {
        return "";
    }
    const tbm = q.get("tbm") || "", udm = q.get("udm") || "";
    if (p === "/imghp" || p === "/search" && (tbm === "isch" || udm === "2")) {
        return "images";
    }
    if (p === "/videohp" || p === "/search" && (tbm === "vid" || udm === "7")) {
        return "videos";
    }
    return "";
}
function ugfMobileKind() {
    const p = window.location.pathname;
    if (window.location.host === "maps.google.com" || /^\/maps(\/|$)/.test(p)) {
        return "maps";
    }
    let q;
    try {
        q = new URLSearchParams(window.location.search);
    } catch (e) {
        return null;
    }
    if ((p === "/" || p === "/webhp") && !q.get("q") || ugfMobileVertical()) {
        return "home";
    }
    if (p !== "/search" || !q.get("q")) {
        return null;
    }
    const tbm = q.get("tbm") || "", udm = q.get("udm") || "";
    if (tbm === "isch" || udm === "2") {
        return "images";
    }
    if (tbm === "vid" || udm === "7") {
        return "videos";
    }
    if (tbm === "nws" || udm === "12") {
        return "news";
    }
    if (tbm || (udm && udm !== "14")) {
        return null;   // (Shopping, Books and the rest keep the desktop look)
    }
    return "all";
}
function ugfMEsc(s) {
    return String(s === null || s === undefined ? "" : s).replace(/[&<>"']/g, function(c) {
        return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
}
function ugfMUrl(kind, q) {
    const e = encodeURIComponent(q || "");
    if (!q) {
        return { all: "/", images: "/imghp", videos: "/videohp", news: "https://news.google.com/", maps: "https://www.google.com/maps",
            shopping: "/shopping", books: "https://books.google.com/" }[kind] || "/";
    }
    return {
        all: "/search?q=" + e, images: "/search?q=" + e + "&tbm=isch", videos: "/search?q=" + e + "&tbm=vid",
        news: "/search?q=" + e + "&tbm=nws", maps: "https://www.google.com/maps?q=" + e, shopping: "/search?q=" + e + "&tbm=shop",
        books: "/search?q=" + e + "&tbm=bks"
    }[kind] || "/search?q=" + e;
}
