// (8.26) who is signed in: what the bar learnt (html[logged-in], the name, address and photo it keeps)
function ugfMobileWho() {
    const h = document.documentElement;
    if (!h || h.getAttribute("logged-in") !== "true") {
        return null;
    }
    const text = function(sel, blank) {
        const el = document.querySelector(sel);
        const t = el ? String(el.textContent || "").trim() : "";
        return t === blank ? "" : t;
    };
    const pfp = document.querySelector("#ugf-account-pfp img");
    let name = text("#ugf-account-username span", "Account");
    let mail = text("#ugf-account-email span", "Email");
    let photo = pfp ? String(pfp.getAttribute("src") || "") : "";
    try {
        name = name || String(GM_getValue("UGF_USERNAME", "") || "");
        mail = mail || String(GM_getValue("UGF_EMAIL", "") || "");
        photo = photo || String(GM_getValue("UGF_PFP", "") || "");
    } catch (e) {}
    if (!name && !mail) {
        return null;
    }
    return { name: name, email: mail, photo: /^(https?:|data:)/.test(photo) ? photo : "", first: name.split(" ")[0] || "" };
}
// the photo at a size, or the first letter on blue
function ugfMobilePhoto(w, size) {
    if (w.photo) {
        const src = w.photo.replace(/=s\d+(-[a-z-]*)?$/, "=s" + size + "-c").replace(/\/s\d+(-c)?\//, "/s" + size + "-c/");
        return '<img class="m-acct-pic" src="' + ugfMEsc(src) + '" width="' + size + '" height="' + size + '" alt="">';
    }
    return '<span class="m-acct-pic m-acct-letter">' + ugfMEsc((w.first || w.email || "?").charAt(0).toUpperCase()) + "</span>";
}
// the account where each period showed it: "top" is the 2015-2016 home page's right end (the Sign in button, or
