// the lightweight page's knowledge panel (the picture, name, a line about them, the Wikipedia text and
// the facts), as the card the mobile site put above the results from late 2012
function ugfMClean(node, out) {
    node.childNodes.forEach(function(n) {
        if (n.nodeType === 3) {
            out.appendChild(document.createTextNode(n.nodeValue));
        } else if (n.nodeType === 1 && !/^(SCRIPT|STYLE|IMG|SVG)$/i.test(n.nodeName)) {
            if (n.nodeName === "A" && n.getAttribute("href")) {
                const a = document.createElement("a");
                a.href = n.href;
                a.textContent = n.textContent;
                out.appendChild(a);
            } else {
                ugfMClean(n, out);
            }
        }
    });
    return out;
}
function ugfMobileKp(era) {
    if (era === "a" || era === "b1") {
        return;
    }
    const have = document.getElementById("ugf-m-kp");
    let box = null;
    const imgs = document.querySelectorAll("img.hIJyHe");
    for (let i = 0; i < imgs.length && !box; i++) {
        const b = imgs[i].closest(".Gx5Zad");
        if (b && !b.closest("#ugf") && b.querySelector(".xpc") && b.querySelector("h3")) {
            box = b;
        }
    }
    if (!box) {
        return;
    }
    const srcImg = box.querySelector("img.hIJyHe");
    if (have) {
        const im = have.querySelector(".m-kp-img img");
        if (im && srcImg && im.src !== srcImg.src && !/^data:image\/gif/.test(srcImg.src)) {
            im.src = srcImg.src;
        }
        return;
    }
    const list = document.getElementById("ugf-search-results-container");
    if (!list || !document.documentElement.hasAttribute("results-arrived") && !list.querySelector(".ugf-search-result")) {
        return;
    }
    const card = document.createElement("div");
    card.id = "ugf-m-kp";
    const head = document.createElement("div");
    head.className = "m-kp-head";
    if (srcImg && srcImg.src) {
        const iw = document.createElement("div");
        iw.className = "m-kp-img";
        const im = document.createElement("img");
        im.src = srcImg.src;
        im.alt = "";
        iw.appendChild(im);
        head.appendChild(iw);
    }
    const t = document.createElement("div");
    t.className = "m-kp-title";
    t.textContent = box.querySelector("h3").textContent;
    head.appendChild(t);
    const subEl = box.querySelector(".lQigmf .d6Ejqe");
    if (subEl && !subEl.closest(".xpc")) {
        const sub = document.createElement("div");
        sub.className = "m-kp-sub";
        sub.textContent = subEl.textContent;
        head.appendChild(sub);
    }
    card.appendChild(head);
    const xpc = box.querySelector(".xpc");
    let descEl = null;
    xpc.querySelectorAll(".H66NU").forEach(function(d) {
        if (!descEl && !d.closest(".Y0EWEb") && !d.querySelector(".H66NU") && d.textContent.length > 40) {
            descEl = d;
        }
    });
    if (descEl) {
        const d = document.createElement("div");
        d.className = "m-kp-desc";
        ugfMClean(descEl, d);
        card.appendChild(d);
    }
    xpc.querySelectorAll(".Y0EWEb").forEach(function(f) {
        const row = document.createElement("div");
        row.className = "m-kp-fact";
        ugfMClean(f, row);
        const txt = row.textContent;
        const cut = txt.indexOf(":");
        if (cut > 0 && cut < 40) {
            // (the label, "Born:", in bold, as the card had it)
            const label = document.createElement("b");
            label.textContent = txt.slice(0, cut + 1);
            let left = cut + 1;
            while (row.firstChild && left > 0) {
                const n = row.firstChild;
                const len = n.textContent.length;
                if (len <= left) {
                    row.removeChild(n);
                    left -= len;
                } else {
                    if (n.nodeType === 3) {
                        n.nodeValue = n.nodeValue.slice(left);
                    }
                    left = 0;
                }
            }
            row.insertBefore(label, row.firstChild);
        }
        card.appendChild(row);
    });
    list.parentNode.insertBefore(card, list);
}
// "Showing results for ... / Search instead for ..." (and "Did you mean"), above the results
function ugfMobileSpell() {
    if (document.getElementById("ugf-m-spell")) {
        return;
    }
    const list = document.getElementById("ugf-search-results-container");
    if (!list || !list.querySelector(".ugf-search-result")) {
        return;
    }
    const lines = [];
    document.querySelectorAll(".Va3FIb").forEach(function(l) {
        if (!l.closest("#ugf") && /^\s*(Showing results for|Including results for|Did you mean|Search instead for)/i.test(l.textContent) && l.querySelector("a")) {
            lines.push(l);
        }
    });
    if (!lines.length) {
        return;
    }
    const box = document.createElement("div");
    box.id = "ugf-m-spell";
    lines.slice(0, 2).forEach(function(l, i) {
        const d = document.createElement("div");
        d.className = "m-sp" + (i + 1);
        ugfMClean(l, d);
        box.appendChild(d);
    });
    const kp = document.getElementById("ugf-m-kp");
    list.parentNode.insertBefore(box, kp || list);
}
// Images: the thumbnails Google's phone page lists, as a grid; tap one for the picture on black, with
// the page it's from (the way the mobile site showed them)
function ugfMobileImages() {
    if (document.getElementById("ugf-m-images")) {
        return;
    }
    const head = document.getElementById("ugf-m-head");
    const items = [];
    document.querySelectorAll(".isv-r[data-ou], .isv-r[data-ru]").forEach(function(n) {
        if (n.closest("#ugf")) {
            return;
        }
        const img = n.querySelector("img");
        let thumb = img ? img.getAttribute("src") || "" : "";
        if (!thumb || thumb.length < 200 && /^data:/.test(thumb)) {
            thumb = img ? img.getAttribute("data-src") || thumb : thumb;
        }
        if (!thumb) {
            return;
        }
        const w = parseFloat(n.getAttribute("data-ow")) || parseFloat(n.getAttribute("data-tw")) || 4;
        const h = parseFloat(n.getAttribute("data-oh")) || 3;
        items.push({ thumb: thumb, full: n.getAttribute("data-ou") || thumb, page: n.getAttribute("data-ru") || "", title: n.getAttribute("data-pt") || "",
            site: n.getAttribute("data-st") || "", ratio: Math.max(0.4, Math.min(2.5, w / h)), w: w, h: h });
    });
    if (!head || !items.length) {
        return;
    }
    const grid = document.createElement("div");
    grid.id = "ugf-m-images";
    items.forEach(function(it, i) {
        const a = document.createElement("a");
        a.className = "m-im";
        a.href = it.page || it.full;
        a.style.webkitFlexGrow = a.style.flexGrow = String(it.ratio);
        a.style.webkitFlexBasis = a.style.flexBasis = Math.round(it.ratio * 74) + "px";
        const img = document.createElement("img");
        img.src = it.thumb;
        img.alt = it.title;
        a.appendChild(img);
        a.addEventListener("click", function(ev) {
            ev.preventDefault();
            ugfMobileViewer(items, i);
        });
        grid.appendChild(a);
    });
    head.parentNode.insertBefore(grid, head.nextSibling);
    document.documentElement.setAttribute("ugf-m-grid", "");
}
function ugfMobileViewer(items, i) {
    let v = document.getElementById("ugf-m-iv");
    if (!v) {
        v = document.createElement("div");
        v.id = "ugf-m-iv";
        v.innerHTML = ugfTT('<div class="m-iv-bar"><a class="m-iv-x" href="#" aria-label="Close">×</a><span class="m-iv-n"></span></div>' +
            '<div class="m-iv-pic"><img alt=""><a class="m-iv-prev" href="#" aria-label="Previous">‹</a><a class="m-iv-next" href="#" aria-label="Next">›</a></div>' +
            '<div class="m-iv-info"><div class="m-iv-title"></div><div class="m-iv-site"></div><div class="m-iv-size"></div>' +
            '<div class="m-iv-btns"><a class="m-iv-visit" href="#">Visit page</a><a class="m-iv-full" href="#">View image</a></div></div>');
        document.getElementById("ugf").appendChild(v);
        v.querySelector(".m-iv-x").addEventListener("click", function(ev) {
            ev.preventDefault();
            document.documentElement.removeAttribute("ugf-m-iv-open");
        });
        v.querySelector(".m-iv-prev").addEventListener("click", function(ev) {
            ev.preventDefault();
            ugfMobileViewer(v.ugfItems, Math.max(0, v.ugfIndex - 1));
        });
        v.querySelector(".m-iv-next").addEventListener("click", function(ev) {
            ev.preventDefault();
            ugfMobileViewer(v.ugfItems, Math.min(v.ugfItems.length - 1, v.ugfIndex + 1));
        });
    }
    const it = items[i];
    v.ugfItems = items;
    v.ugfIndex = i;
    const img = v.querySelector(".m-iv-pic img");
    img.onerror = function() {
        img.onerror = null;
        img.src = it.thumb;
    };
    img.src = it.thumb;
    if (it.full && it.full !== it.thumb) {
        const big = new Image();
        big.onload = function() {
            if (v.ugfIndex === i) {
                img.src = it.full;
            }
        };
        big.src = it.full;
    }
    v.querySelector(".m-iv-n").textContent = (i + 1) + " of " + items.length;
    v.querySelector(".m-iv-title").textContent = it.title;
    let host = it.site;
    try {
        host = new URL(it.page).hostname.replace(/^www\./, "");
    } catch (e) {}
    v.querySelector(".m-iv-site").textContent = host;
    v.querySelector(".m-iv-size").textContent = it.w && it.h && it.w > 4 ? Math.round(it.w) + " × " + Math.round(it.h) : "";
    v.querySelector(".m-iv-visit").href = it.page || it.full;
    v.querySelector(".m-iv-full").href = it.full;
    v.querySelector(".m-iv-prev").style.visibility = i > 0 ? "" : "hidden";
    v.querySelector(".m-iv-next").style.visibility = i < items.length - 1 ? "" : "hidden";
    document.documentElement.setAttribute("ugf-m-iv-open", "");
}
// "Classic" on a phone: the desktop page, laid out at desktop width (zoomed out, as Safari showed
// desktop sites), with a way back to the phone layout at the bottom
function ugfMobileClassic() {
    let classic = false;
    try {
        classic = sessionStorage.getItem("ugf_m_classic") === "1";
    } catch (e) {}
    if (!classic || ugfMobileMode() === "off") {
        return;
    }
    const setViewport = function() {
        let vp = document.querySelector('meta[name="viewport"]');
        if (!vp && document.head) {
            vp = document.createElement("meta");
            vp.name = "viewport";
            document.head.appendChild(vp);
        }
        const sw = Math.min(window.screen.width || 375, window.screen.height || 667);
        const want = "width=1100, initial-scale=" + (sw / 1100).toFixed(3) + ", minimum-scale=0.2, maximum-scale=5, user-scalable=yes";
        if (vp && vp.getAttribute("content") !== want) {
            vp.setAttribute("content", want);
        }
    };
    setViewport();
    let tries = 0;
    const iv = setInterval(function() {
        tries++;
        setViewport();
        const root = document.getElementById("ugf");
        if (root && !document.getElementById("ugf-m-back")) {
            const d = document.createElement("div");
            d.id = "ugf-m-back";
            d.style.cssText = "clear:both;text-align:center;font:16px arial,sans-serif;padding:18px 0 26px;color:#000";
            d.appendChild(document.createTextNode("View Google in: "));
            const a = document.createElement("a");
            a.href = "#";
            a.textContent = "Mobile";
            a.style.color = "#00c";
            a.addEventListener("click", function(ev) {
                ev.preventDefault();
                try {
                    sessionStorage.removeItem("ugf_m_classic");
                } catch (e) {}
                window.location.reload();
            });
            d.appendChild(a);
            const b = document.createElement("b");
            b.textContent = " | Classic";
            d.appendChild(b);
            root.appendChild(d);
        }
        if (tries > 100) {
            clearInterval(iv);
        }
    }, 100);
}
// Maps on a phone: Gplex's Maps page (the map of your layout's year) laid out the way Google's
// mobile Maps was - the search on top and the map filling the rest of the screen, moved with a
// finger and zoomed with two - with the results in a strip under the map on the older layouts
function ugfMobileMaps() {
    const setViewport = function() {
        let vp = document.querySelector('meta[name="viewport"]');
        if (!vp && document.head) {
            vp = document.createElement("meta");
            vp.name = "viewport";
            document.head.appendChild(vp);
        }
        const want = "width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no";
        if (vp && vp.getAttribute("content") !== want) {
            vp.setAttribute("content", want);
        }
    };
    setViewport();
    let tries = 0;
    const iv = setInterval(function() {
        tries++;
        setViewport();
        const shell = document.getElementById("ugf-maps");
        const wrap = shell && shell.querySelector("#ugf-maps-mapwrap");
        const era = shell && shell.getAttribute("era");
        if (wrap && era && !document.getElementById("ugf-m-mapzoom")) {
            // the old big pan-and-zoom control doesn't fit a phone and the later small one is hidden
            // there: plain + and - buttons (as the mobile Maps of 2005-2011 had; a phone that does not
            // pinch has no other way), doing what the controls' own buttons do
            const z = document.createElement("div");
            z.id = "ugf-m-mapzoom";
            z.className = "ugf-maps-ctl";
            z.innerHTML = ugfTT('<a href="#" class="m-zi" aria-label="Zoom in">+</a><a href="#" class="m-zo" aria-label="Zoom out">−</a>');
            wrap.appendChild(z);
            const press = function(cls) {
                return function(ev) {
                    ev.preventDefault();
                    const b = wrap.querySelector(".ugf-maps-ctl:not(#ugf-m-mapzoom) ." + cls);
                    if (b) {
                        b.click();
                    }
                };
            };
            z.querySelector(".m-zi").addEventListener("click", press("zi"));
            z.querySelector(".m-zo").addEventListener("click", press("zo"));
        }
        if (tries > 300) {
            clearInterval(iv);
        }
    }, 100);
}
// (8.33) The Phone layout at the phone's width: a page without a viewport meta is laid out at 980px by Firefox for
// Android, which left the layout tiny (from the Google Turbo Gold fork). The Classic view and Maps set their own.
function ugfMobileViewport() {
    try {
        let vp = document.querySelector('meta[name="viewport"]');
        if (!vp && document.head) {
            vp = document.createElement("meta");
            vp.name = "viewport";
            document.head.appendChild(vp);
        }
        if (vp && !/width\s*=\s*device-width/.test(vp.getAttribute("content") || "")) {
            vp.setAttribute("content", "width=device-width, initial-scale=1");
        }
    } catch (e) {}
}
function ugfMobileBoot() {
    if (window.top !== window.self || window.location.host !== "www.google.com" && window.location.host !== "maps.google.com") {
        return;
    }
    const kind = ugfMobileKind();
    if (!kind) {
        return;
    }
    if (kind === "maps") {
        // ("Classic" is for Search; Maps goes by the Phone layout setting alone)
        if (ugfPhoneLayout()) {
            const h = document.documentElement;
            h.setAttribute("ugf-mobile", "");
            h.setAttribute("ugf-m-kind", "maps");
            const ms = document.createElement("style");
            ms.id = "ugf-mobile-css";
            ms.textContent = UGF_M_CSS.split("__SPRITE__").join(UGF_M_ASSETS.sprite);
            (document.head || h).appendChild(ms);
            ugfMobileMaps();
        }
        return;
    }
    if (!ugfMobileWanted()) {
        ugfMobileClassic();
        return;
    }
    const L = ugfMobileLayout();
    const era = ugfMobileEra(L);
    const year = ugfMobileYear(L, era);
    const html = document.documentElement;
    if (!html) {
        return;
    }
    html.setAttribute("ugf-mobile", "");
    html.setAttribute("ugf-m", era);
    html.setAttribute("ugf-m-kind", kind);
    const st = document.createElement("style");
    st.id = "ugf-mobile-css";
    st.textContent = UGF_M_CSS.split("__SPRITE__").join(UGF_M_ASSETS.sprite) + "\n" + UGF_M_ACCT_CSS;
    (document.head || html).appendChild(st);
    let tries = 0;
    const iv = setInterval(function() {
        tries++;
        if (!document.getElementById("ugf-mobile-css")) {
            (document.head || html).appendChild(st);
        }
        ugfMobileViewport();
        const built = document.body && ugfMobileBuild(era, kind, year);
        if (built) {
            ugfMobileAccountSync(era);
            ugfMobileTidy(era);
            ugfMobileKp(era);
            ugfMobileSpell();
            if (kind === "images") {
                ugfMobileImages();
            }
        }
        if (tries > 600) {
            clearInterval(iv);
        }
    }, 100);
}
function ugfMobileMenu() {
    if (window.top !== window.self || window.location.host !== "www.google.com" && window.location.host !== "maps.google.com") {
        return;
    }
    const m = ugfMobileMode();
    const labels = { auto: "Phone layout: Auto (switch to On)", on: "Phone layout: On (switch to Off)", off: "Phone layout: Off (switch to Auto)" };
    GM_registerMenuCommand(labels[m] || labels.auto, function() {
        GM_setValue("UGF_MOBILE", { auto: "on", on: "off", off: "auto" }[m] || "on");
        try {
            sessionStorage.removeItem("ugf_m_classic");
        } catch (e) {}
        window.location.reload();
    });
}
ugfMobileMenu();
ugfMobileBoot();
