    function doSearchValueStuff() {
        if (!searchValue) {
            // (6.5.3) the search box wasn't readable yet (lightweight pages): the address has the search
            try {
                searchValue = new URLSearchParams(window.location.search).get("q") || "";
            } catch (e) {}
        }
        if (
            location !== "home" &&
            location !== "gplex"
        ) {
            fixSidebar();
        }
        setLayout();
        createTop();
        ugfBreakoutMaybe();
    }
    // (8.12) "Atari Breakout" in Image Search on the 2013-2019 layouts (Google's from 13 May 2013 to 2020): the game
    // starts once the pictures have come in, which is when their count has held still for a second
    function ugfBreakoutMaybe() {
        const h = document.documentElement;
        if (location !== "images" || String(searchValue || "").trim().toLowerCase() !== "atari breakout" ||
            !/^201[3-9]/.test(h.getAttribute("layout") || "") || h.hasAttribute("ugf-mobile") || h.hasAttribute("ugf-breakout")) {
            return;
        }
        let seen = -1;
        let still = 0;
        let ticks = 0;
        const t = window.setInterval(function() {
            const area = document.querySelector("#ugf-image-results");
            const pics = area ? Array.prototype.filter.call(area.querySelectorAll(".ugf-image-result img"), function(im) {
                return im.complete && im.naturalWidth > 0;
            }) : [];
            still = pics.length && pics.length === seen ? still + 1 : 0;
            seen = pics.length;
            if (still >= 3 || ++ticks > 60) {
                window.clearInterval(t);
                if (pics.length >= 6 && !h.hasAttribute("ugf-breakout")) {
                    ugfBreakout(area, pics);
                }
            }
        }, 300);
    }
    function fixSidebar() {
        let encodedSearchValue = encodeURIComponent(searchValue);
        let sidebarTools = document.querySelectorAll(".ugf-sidebar-tool-inner");
        sidebarTools.forEach(itemRoot => {
            let newHref = itemRoot.getAttribute("href").replaceAll("TEMP_REPLACEME",encodedSearchValue);
            itemRoot.setAttribute("href",newHref);
        });
    }
    function fixPagination() {
        fixPagination.done = true;
        let encodedSearchValue = encodeURIComponent(searchValue);
        let pages = document.querySelectorAll(".gp-pagination");
        let PRcheck = 0;
        pages.forEach(itemRoot => {
            let newHref;
            if (location == "images") {
                newHref = itemRoot.getAttribute("href").replaceAll("TEMP_REPLACEME",encodedSearchValue + "&udm=2");
            } else if (location == "videos") {
                newHref = itemRoot.getAttribute("href").replaceAll("TEMP_REPLACEME",encodedSearchValue + "&udm=7");
            } else if (location == "news" && document.querySelector("html").hasAttribute("news-results")) {
                newHref = itemRoot.getAttribute("href").replaceAll("TEMP_REPLACEME",encodedSearchValue + "&tbm=nws");
            } else {
                newHref = itemRoot.getAttribute("href").replaceAll("TEMP_REPLACEME",encodedSearchValue);
            }
            if (document.querySelector("html").hasAttribute("basic-html") && newHref.indexOf("gbv=1") === -1) {
                newHref += "&gbv=1";
            }
            itemRoot.setAttribute("href",newHref);
            PRcheck++;
        });
        let newPrevHref;
        let newNextHref;
        let pageSuffix = "";
        if (location == "images") {
            pageSuffix = "&udm=2";
        } else if (location == "videos") {
            pageSuffix = "&udm=7";
        } else if (location == "news" && document.querySelector("html").hasAttribute("news-results")) {
            pageSuffix = "&tbm=nws";
        }
        if (document.querySelector("html").hasAttribute("basic-html")) {
            pageSuffix += "&gbv=1";
        }
        const pageBase = "https://www.google.com/search?q=" + encodedSearchValue + pageSuffix;
        const pageLinks = document.querySelectorAll("#gp-page-numbers .gp-pagination");
        const blockStart = Math.floor((page - 1) / 10) * 10 + 1;
        pageLinks.forEach(function(link, i) {
            const num = blockStart + i;
            const startAt = (num - 1) * 10;
            link.setAttribute("href", pageBase + (startAt ? "&start=" + startAt : ""));
            const label = link.querySelector("span");
            if (label) {
                label.textContent = String(num);
            }
            link.classList.remove("active");
            if (num === page) {
                link.classList.add("active");
            }
        });
        if (page > 1) {
            const prevStart = (page - 2) * 10;
            newPrevHref = pageBase + (prevStart ? "&start=" + prevStart : "");
        }
        newNextHref = pageBase + "&start=" + (page * 10);
        if (document.querySelector("#gp-pagination-prev") && newPrevHref) {
            document.querySelector("#gp-pagination-prev").setAttribute("href",newPrevHref);
        }
        if (document.querySelector("#gp-pagination-next")) {
            document.querySelector("#gp-pagination-next").setAttribute("href",newNextHref);
        }
        if (page != 1) {
            document.querySelector("#gp-pagination-prev").classList.add("has-prev");
        }
    }
    function ugfFaviconForLayout() {
        const h = document.querySelector("html");
        const era = ugfRetroEra();
        // 2009/2010 eras used the multicolour tile; 1997-2008 used the blue G with coloured edges
        if (era === "gplex2009") {
            // the blue "g" of June 2008 gave way to the four-colour tile in January 2009,
            // so Late 2009-Early 2010 has the tile 2010-2011 uses; Late 2008-2009 keeps the "g"
            return h.hasAttribute("gplex2009l") ? UGF_FAVICON_2010 : UGF_FAVICON_2009_G;
        }
        if (era === "gplex2010") {
            return UGF_FAVICON_2010;
        }
        if (era && era !== "gplex2022") {
            return UGF_FAVICON_1999;
        }
        if (era === "gplex2022") {
            return UGF_FAVICON_2015;
        }
        const layout = h.getAttribute("layout") || "";
        if (["2010", "2011", "2012"].indexOf(layout) > -1) {
            return UGF_FAVICON_2010;
        }
        if (["2013", "2013L", "2014", "2015", "2015L"].indexOf(layout) > -1) {
            return UGF_FAVICON_2012;
        }
        if (["2016", "2016C", "2016L", "2017", "2018", "2018M", "2019"].indexOf(layout) > -1) {
            return UGF_FAVICON_2015;
        }
        if (layout === "retro") {
            return UGF_FAVICON_1999;
        }
        return null;
    }
    let ugfFaviconObserver = null;
