            if ((v.view === "home" || v.view === "root") && era !== "dl10" && era !== "dl11" && !tick.left) {
                tick.left = true;
                go("my-drive");
            }
            myTitle = titleFor();
            if (document.title !== myTitle) {
                document.title = myTitle;
            }
            harvest();
