            add(".gvarr", "position: absolute; top: 50%; transform: translateY(-50%); color: #fff; opacity: 0; transition: opacity .15s; display: flex;");
            add(".gvimg:hover .gvarr", "opacity: .8;");
            add(".gvarr.l", "left: 8px;");
            add(".gvarr.r", "right: 8px;");
            add(".gvarr.off", "display: none;");
