    // (8.18) the period's coverage tiles: Google's blue lines of 2008 to 2017, which its Maps API still
    // draws, and the lines with the photo-sphere rings of the Maps of 2018 on
    function ugfMapsCoverage(era) {
        const modern = era === "m2019" || era === "m2022";
        return { url: function(x, y, z) {
            return modern
                ? "https://www.google.com/maps/vt?pb=!1m5!1m4!1i" + z + "!2i" + x + "!3i" + y + "!4i256!2m8!1e2!2ssvv!4m2!1scb_client!2sapiv3" +
                    "!4m2!1scc!2s*211m3*211e3*212b1*213e2*211m3*211e2*212b1*213e2!3m3!3sUS!12m1!1e68!4e0"
                : "https://mts" + ((x + y) % 2) + ".googleapis.com/vt?hl=" + encodeURIComponent(ugfMapsLang()) + "&lyrs=svv%7Ccb_client:apiv3&style=40,18&x=" + x + "&y=" + y + "&z=" + z;
        } };
    }
    function ugfMapsScale(map) {
        const mpp = map.metersPerPixel();
        const us = /^en-(US|LR|MM)$/i.test(navigator.language || "") || /^en$/i.test(navigator.language || "");
        const nice = function(max, units) {
            for (let i = units.length - 1; i >= 0; i--) {
                if (units[i][0] <= max) {
                    return units[i];
                }
            }
            return units[0];
        };
        if (us) {
            const ft = mpp * 3.28084 * 90;
            const u = ft < 5280 ? nice(ft, [[10, "10 ft"], [20, "20 ft"], [50, "50 ft"], [100, "100 ft"], [200, "200 ft"], [500, "500 ft"], [1000, "1000 ft"], [2000, "2000 ft"]])
                : nice(ft / 5280, [[0.5, "0.5 mi"], [1, "1 mi"], [2, "2 mi"], [5, "5 mi"], [10, "10 mi"], [20, "20 mi"], [50, "50 mi"], [100, "100 mi"], [200, "200 mi"], [500, "500 mi"], [1000, "1000 mi"], [2000, "2000 mi"]]);
            const px = ft < 5280 ? u[0] / 3.28084 / mpp : u[0] * 1609.344 / mpp;
            return { px: Math.round(px), label: u[1] };
        }
        const mm = mpp * 90;
        const u = mm < 1000 ? nice(mm, [[5, "5 m"], [10, "10 m"], [20, "20 m"], [50, "50 m"], [100, "100 m"], [200, "200 m"], [500, "500 m"]])
            : nice(mm / 1000, [[1, "1 km"], [2, "2 km"], [5, "5 km"], [10, "10 km"], [20, "20 km"], [50, "50 km"], [100, "100 km"], [200, "200 km"], [500, "500 km"], [1000, "1000 km"], [2000, "2000 km"]]);
        const px = mm < 1000 ? u[0] / mpp : u[0] * 1000 / mpp;
        return { px: Math.round(px), label: u[1] };
    }
    function ugfMapsIdentity() {
        let name = "";
        try {
            name = typeof GM_getValue === "function" ? String(GM_getValue("UGF_USERNAME", "") || "") : "";
        } catch (e) {}
        const a = document.querySelector('a[aria-label*="@"]');
        // the Maps page names the account too, the way Gmail's does
        name = name || ugfGmailIdentity().name || "";
        const signedIn = !!a || !!name;
        return { name: name.split(" ")[0] || "", signedIn: signedIn };
    }
    // The Google bar, one per period, as Gplex draws it on google.com
    function ugfMapsGbar(era) {
        const who = ugfMapsIdentity();
        const esc = ugfMapsEsc;
        // late 2012 to 2013: the +You bar (bold links, +Name first, nothing on the right)
        const lay = String(layout || "");
        const plusBar = lay === "2013";
        const dark = era === "m2011" || plusBar;
        const apps = dark
            ? [["Search", "https://www.google.com/"], ["Images", "https://www.google.com/imghp"], ["Maps", ""],
                ["Play", "https://play.google.com/"], ["YouTube", "https://www.youtube.com/"], ["News", "https://news.google.com/"],
                ["Gmail", "https://mail.google.com/"], [ugfDocsLabel(), "https://docs.google.com/document/"], ["Drive", "https://drive.google.com/"], ["Calendar", "https://calendar.google.com/"]].filter(ugfDvGbarKeep)
            : [["Web", "https://www.google.com/"], ["Images", "https://www.google.com/imghp"],
                [era === "m2010" ? "Videos" : "Video", "https://www.google.com/videohp"], ["Maps", ""],
                ["News", "https://news.google.com/"], ["Shopping", "https://www.google.com/shopping"],
                ["Gmail", "https://mail.google.com/"], [ugfDocsLabel(), "https://docs.google.com/document/"]].filter(ugfDvGbarKeep);
        // Late 2012-2013 (layout 2013, not the legacy 2013L) is the +You bar: +Name leads
        // the links, the current product is just the white highlight, and the right side
        // is only the gear - the name / count / Share / photo block sits in the header.
        const late = plusBar;
        let links = late
            ? '<a class="plus" href="' + esc(ugfPlusProfileLink()) + '">+' + esc(ugfGmailPlusName()) + "</a>"
            : "";
        apps.forEach(function(a) {
            links += a[1] ? '<a href="' + esc(a[1]) + '">' + esc(a[0]) + "</a>" : '<a class="here">' + esc(a[0]) + "</a>";
        });
        links += '<a href="https://www.google.com/intl/en/about/products/" class="more">' +
            (dark ? "More" : "more") + " &#9662;</a>";
        const right = late
            ? ""
            : era === "m2011"
            ? (who.name ? '<a class="who" href="https://myaccount.google.com/">' + esc(who.name) + "</a>" : '<a href="https://accounts.google.com/ServiceLogin">Sign in</a>')
            : '<a href="https://www.google.com/ig">iGoogle</a><span class="sepr">|</span>' +
              '<a href="https://www.google.com/gplex">Search settings</a><span class="sepr">|</span>' +
              (who.name ? '<a class="who" href="https://myaccount.google.com/">' + esc(who.name) + "</a>" : '<a href="https://accounts.google.com/ServiceLogin">Sign in</a>');
        return '<div id="ugf-maps-gbar" class="' + (dark ? (late ? "dark late" : "dark") : era === "m2010" ? "g2010" : "plain") + '">' +
            '<div class="left">' + links + '</div><div class="right">' + right + "</div></div>";
    }
    // The header account block of the +You years, as Gplex draws it on Gmail and
