    function ugf2009WaitFor(selector, callback) {
        let tries = 0;
        const interval = setInterval(function() {
            const element = document.querySelector(selector);
            if (element) {
                clearInterval(interval);
                callback(element);
            } else if (++tries > 150) {
                clearInterval(interval);
            }
        }, 100);
    }
    // Classic Google put the buttons in the same centred cell as the search box (input<br>buttons)
    function ugfEraHomeButtons() {
        const era = ugfRetroEra();
        if (!era || era === "gplex2010" || era === "gplex2022") {
            return;
        }
        const loc = document.querySelector("html").getAttribute("location") || "";
        if (!/home$/.test(loc)) {
            return;
        }
        if (era === "gplex2009") {
            ugf2009WaitFor("#ugf-structured-hp-footer-left .ugf-structured-hp-footer-link", function() {
                const labels = ["Advertising Programs", "Business Solutions", "About Google"];
                document.querySelectorAll("#ugf-structured-hp-footer-left .ugf-structured-hp-footer-link").forEach(function(a, i) {
                    if (labels[i]) {
                        a.textContent = labels[i];
                    }
                });
            });
        }
        ugf2009WaitFor("#ugf-hp-search #ugf-search-outer", function(outer) {
            const row = document.querySelector("#ugf-hp-buttons-row");
            if (row && row.parentElement !== outer) {
                outer.appendChild(row);
            }
        });
    }
    // imghp / videohp: logo label, button labels, active tabs
    function ugfVerticalHome() {
        if (!ugfHomeVertical) {
            return;
        }
        const isImages = ugfHomeVertical === "images";
        const isShopping = ugfHomeVertical === "shopping";
        const shopEra = ugfRetroEra();
        const froogle = ["gplex2003", "gplex2005", "gplex2006"].indexOf(shopEra) > -1;
        const productSearch = shopEra === "gplex2007";
        const shopName = froogle ? "Froogle" : (productSearch ? "Product Search" : "Shopping");
        document.title = isShopping ? (froogle ? "Froogle" : (productSearch ? "Google Product Search" : "Google Shopping")) : (isImages ? "Google Images" : "Google Videos");
        ugf2009WaitFor("#ugf-hp-logo-companion", function(comp) {
            const lay = String(layout || "");
            // (8.8) until September 2013 Images drew its logo with the word inside the picture (276x110)
            if (isImages && /^(2012|2013|2013L)$/.test(lay)) {
                document.querySelector("#melvin-hp-logo").src = "https://www.google.com/intl/en_ALL/images/logos/images_logo_lg.gif";
                return;
            }
            if (!comp.querySelector("#ugf-hp-vertical-label")) {
                const lab = document.createElement("div");
                lab.id = "ugf-hp-vertical-label";
                const old = document.querySelector("html").hasAttribute("legacy-gbar");
                const cap = old || lay === "2014" || lay === "2015";   // "Images" again from late 2013
                if (isShopping) {
                    lab.textContent = (froogle || productSearch) ? shopName : lay === "2012" ? "product search" : (cap ? "Shopping" : "shopping");
                } else {
                    lab.textContent = isImages ? (cap ? "Images" : "images") : (old ? "Video" : "videos");
                }
                comp.appendChild(lab);
            }
        });
        const label = isShopping ? (productSearch ? "Search Products" : "Search " + shopName) : (isImages ? "Search Images" : "Search Video");
        ugf2009WaitFor("#ugf-hp-buttons", function(row) {
            const relabel = function() {
                const retro = row.querySelectorAll("button.searchbtn");
                if (retro.length) {
                    retro[0].textContent = label;
                    for (let i = 1; i < retro.length; i++) {
                        retro[i].style.display = "none";
                    }
                }
                const s2 = document.querySelector("#ugf-search-btn-2 span");
                if (s2) {
                    s2.textContent = label;
                }
                return retro.length;
            };
            relabel();
            let n = 0;
            const t = setInterval(function() {
                n++;
                if (relabel() || n > 30) {
                    clearInterval(t);
                }
            }, 100);
        });
        if (isShopping) {
            ugf2009WaitFor("#ugf-top, #ugf-hp-search", function() {
                ugfShoppingNav();
                setTimeout(ugfShoppingNav, 500);
            });
        }
        ugf2009WaitFor("#gp-gbar-inner", function() {
            const search = document.querySelector("#gp-gbar-search");
            const images = document.querySelector("#gp-gbar-images");
            if (isImages && search && images) {
                search.classList.remove("active");
                images.classList.add("active");
            }
        });
    }
    function ugf2009Buttons() {
        const btnEra = ugfRetroEra();
        if (!btnEra || btnEra === "gplex2010") {
            return;
        }
        if (!/home$/.test(document.querySelector("html").getAttribute("location") || "")) {
            ugf2009WaitFor("#ugf-search", function(searchBar) {
                if (searchBar.querySelector(".searchbtn-small")) {
                    return;
                }
                const sBtn = document.createElement("button");
                sBtn.classList.add("searchbtn-small");
                sBtn.addEventListener("click", function() {
                    document.querySelector("#ugf-search-btn").click();
                });
                sBtn.innerText = "Search";
                searchBar.appendChild(sBtn);
            });
        } else {
            ugf2009WaitFor("#ugf-hp-buttons", function(btnRow) {
                if (btnRow.querySelector(".searchbtn")) {
                    return;
                }
                const gsBtn = document.createElement("button");
                gsBtn.classList.add("searchbtn");
                gsBtn.addEventListener("click", function() {
                    document.querySelector("#ugf-search-btn-2").click();
                });
                gsBtn.innerText = "Google Search";
                const iflBtn = document.createElement("button");
                iflBtn.classList.add("searchbtn");
                iflBtn.addEventListener("click", function() {
                    document.querySelector("#ugf-lucky-btn").click();
                });
                const eraConf = ugfRetroConf(ugfRetroEra());
                iflBtn.innerText = (eraConf && eraConf.luckyLabel) ? eraConf.luckyLabel : "I\'m Feeling Lucky";
                const eraConf2 = ugfRetroConf(ugfRetroEra());
                if (eraConf2 && eraConf2.resultsDropdown) {
                    const sel = document.createElement("select");
                    sel.className = "ugf-era-results-select";
                    eraConf2.resultsDropdown.forEach(function(opt) {
                        const o = document.createElement("option");
                        o.textContent = opt;
                        o.value = String(parseInt(opt, 10) || 10);
                        sel.appendChild(o);
                    });
                    let savedNum = "10";
                    try {
                        savedNum = localStorage.getItem("UGF_ERA_NUM") || "10";
                    } catch (e) {}
                    sel.value = savedNum;
                    if (!sel.value) {
                        sel.value = "10";
                    }
                    sel.addEventListener("change", function() {
                        try {
                            localStorage.setItem("UGF_ERA_NUM", sel.value);
                        } catch (e) {}
                    });
                    btnRow.appendChild(sel);
                }
                btnRow.appendChild(gsBtn);
                btnRow.appendChild(iflBtn);
            });
        }
    }
    ugf2009Buttons();
    ugfEraHomeButtons();
    ugfVerticalHome();
    ugfEraPageLimit();
